{
    struct config_line *line;
    int cur_level = 1;

    if (config->error_message)
        return false;

    while (parser_next(&config->parser, &line)) {
        if (line->type == CONFIG_LINE_TYPE_SECTION) {
            cur_level++;
        } else if (line->type == CONFIG_LINE_TYPE_SECTION_END) {
            cur_level--;

            if (!cur_level)
                return true;
        }
    }

    return false;
